// Utrwalone tytuły redakcyjne Prawa o ruchu drogowym: spis treści
// komentarza C.H.Beck, uzupełniony po sprawdzeniu tekstu ujednoliconego ELI.
const prdReviewed = JSON.parse(fs.readFileSync(new URL("./prd-reviewed-titles.json", import.meta.url), "utf8"));
for (const [id, title] of Object.entries(prdReviewed)) reviewed.set(id, title);

// Tytuły redakcyjne ustawy o cudzoziemcach sprawdzone artykuł po artykule
// na podstawie aktualnego spisu treści oraz treści poszczególnych przepisów.
const cudzReviewed = JSON.parse(fs.readFileSync(new URL("./cudz-reviewed-titles.json", import.meta.url), "utf8"));
for (const [id, title] of Object.entries(cudzReviewed)) reviewed.set(id, title);

// Tytuły redakcyjne ustawy o wspieraniu i resocjalizacji nieletnich
// zweryfikowane ze spisem dla tekstu jednolitego Dz.U. 2026 poz. 163.
const nieletniReviewed = JSON.parse(fs.readFileSync(new URL("./nieletni-reviewed-titles.json", import.meta.url), "utf8"));
for (const [id, title] of Object.entries(nieletniReviewed)) reviewed.set(id, title);

// Tytuły redakcyjne Kodeksu karnego zweryfikowane z aktualnym spisem;
// utrwalone tytuły źródłowe pozostają w sourceTitles i mają pierwszeństwo.
const kkReviewed = JSON.parse(fs.readFileSync(new URL("./kk-reviewed-titles.json", import.meta.url), "utf8"));
for (const [id, title] of Object.entries(kkReviewed)) reviewed.set(id, title);

// Tytuły redakcyjne Kodeksu postępowania karnego zweryfikowane z aktualnym
// spisem oraz treścią każdego przepisu; tytuły źródłowe zachowują pierwszeństwo.
const kpkReviewed = JSON.parse(fs.readFileSync(new URL("./kpk-reviewed-titles.json", import.meta.url), "utf8"));
for (const [id, title] of Object.entries(kpkReviewed)) reviewed.set(id, title);

