for (const [number, title] of Object.entries(kpowReviewed)) reviewed.set(`kpow-art-${number}`, title);

let articles = 0;
let source = 0;
let editorial = 0;
for (const act of data) {
  for (const row of act[3] || []) {
    if (sourceTitles.has(row[0])) row[3] = sourceTitles.get(row[0]);
    else if (reviewed.has(row[0])) row[3] = reviewed.get(row[0]);
    row[3] = String(row[3] || "Zakres przepisu")
      .replace(/\u00ad/g, "")
      .replace(/\s+/g, " ")
      .replace(/[.…]+$/, "")
      .trim();
    row[8] = sourceIds.has(row[0]) ? "s" : "e";
    articles += 1;
    if (row[8] === "s") source += 1;
    else editorial += 1;
  }
}

saveLegalData(data, outputPath);
console.log(JSON.stringify({ status: "ok", articles, source, editorial, outputPath }, null, 2));
